namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public string ImagePlaceholder { get; set; } = "🍽️";
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private static readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1,
            Title = "Classic Pancakes",
            Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
            Ingredients = new() { "1½ cups all-purpose flour", "3½ tsp baking powder", "1 tbsp sugar", "¼ tsp salt", "1¼ cups milk", "1 egg", "3 tbsp melted butter" },
            Steps = new() { "Mix flour, baking powder, sugar, and salt in a bowl.", "Make a well in the center and pour in milk, egg, and melted butter.", "Whisk until smooth.", "Heat a griddle over medium-high heat and lightly oil.", "Pour batter onto the griddle and cook until bubbles form on the surface.", "Flip and cook until browned on the other side.", "Serve with maple syrup and fresh berries." },
            ImagePlaceholder = "🥞",
            TotalRatings = 12,
            RatingSum = 50
        },
        new Recipe
        {
            Id = 2,
            Title = "Avocado Toast",
            Category = "Breakfast",
            Description = "Simple yet delicious avocado toast with a hint of lemon and chili flakes.",
            Ingredients = new() { "2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red chili flakes", "Extra virgin olive oil" },
            Steps = new() { "Toast the sourdough bread until golden and crispy.", "Cut the avocado in half, remove the pit, and scoop into a bowl.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread the avocado mixture onto the toast.", "Drizzle with olive oil and sprinkle with chili flakes.", "Serve immediately." },
            ImagePlaceholder = "🥑",
            TotalRatings = 8,
            RatingSum = 35
        },
        new Recipe
        {
            Id = 3,
            Title = "Spaghetti Bolognese",
            Category = "Main Course",
            Description = "A rich and hearty Italian classic with slow-simmered meat sauce.",
            Ingredients = new() { "400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic, minced", "400g canned crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "1 tsp dried basil", "Salt and pepper", "Parmesan cheese for serving" },
            Steps = new() { "Cook spaghetti according to package directions.", "Brown the ground beef in a large pan over medium-high heat.", "Add onion and garlic, cook until softened.", "Stir in crushed tomatoes, tomato paste, oregano, and basil.", "Simmer on low heat for 20 minutes, stirring occasionally.", "Season with salt and pepper to taste.", "Serve sauce over spaghetti and top with Parmesan cheese." },
            ImagePlaceholder = "🍝",
            TotalRatings = 15,
            RatingSum = 68
        },
        new Recipe
        {
            Id = 4,
            Title = "Grilled Chicken Salad",
            Category = "Salads",
            Description = "A fresh and healthy salad topped with juicy grilled chicken breast.",
            Ingredients = new() { "2 chicken breasts", "6 cups mixed greens", "1 cup cherry tomatoes, halved", "1 cucumber, sliced", "¼ red onion, thinly sliced", "¼ cup crumbled feta cheese", "2 tbsp olive oil", "1 tbsp balsamic vinegar", "Salt and pepper" },
            Steps = new() { "Season chicken breasts with salt, pepper, and olive oil.", "Grill chicken over medium-high heat for 6-7 minutes per side until cooked through.", "Let the chicken rest for 5 minutes, then slice.", "Toss mixed greens, tomatoes, cucumber, and red onion in a large bowl.", "Whisk together olive oil and balsamic vinegar for the dressing.", "Top the salad with sliced chicken and feta cheese.", "Drizzle with dressing and serve." },
            ImagePlaceholder = "🥗",
            TotalRatings = 10,
            RatingSum = 42
        },
        new Recipe
        {
            Id = 5,
            Title = "Chocolate Lava Cake",
            Category = "Dessert",
            Description = "Decadent individual chocolate cakes with a molten center.",
            Ingredients = new() { "200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "¼ cup sugar", "2 tbsp all-purpose flour", "Pinch of salt", "Cocoa powder for dusting" },
            Steps = new() { "Preheat oven to 220°C (425°F). Grease and dust ramekins with cocoa powder.", "Melt chocolate and butter together in a double boiler.", "Whisk eggs, egg yolks, and sugar until thick and pale.", "Fold the chocolate mixture into the egg mixture.", "Sift in flour and salt, fold gently until combined.", "Divide batter among prepared ramekins.", "Bake for 12-14 minutes until edges are firm but center is soft.", "Invert onto plates and serve immediately." },
            ImagePlaceholder = "🍫",
            TotalRatings = 20,
            RatingSum = 95
        },
        new Recipe
        {
            Id = 6,
            Title = "Tiramisu",
            Category = "Dessert",
            Description = "Classic Italian no-bake dessert with layers of espresso-soaked ladyfingers and mascarpone cream.",
            Ingredients = new() { "6 egg yolks", "¾ cup sugar", "500g mascarpone cheese", "2 cups heavy cream", "2 cups strong espresso, cooled", "3 tbsp coffee liqueur (optional)", "24 ladyfinger biscuits", "Cocoa powder for dusting" },
            Steps = new() { "Whisk egg yolks and sugar until thick and pale yellow.", "Add mascarpone cheese and mix until smooth.", "In a separate bowl, whip heavy cream to stiff peaks.", "Fold whipped cream into the mascarpone mixture.", "Combine cooled espresso and coffee liqueur in a shallow dish.", "Quickly dip each ladyfinger into the espresso mixture.", "Arrange a layer of soaked ladyfingers in a dish.", "Spread half the mascarpone cream over the ladyfingers.", "Repeat with another layer of ladyfingers and cream.", "Dust generously with cocoa powder and refrigerate for at least 4 hours." },
            ImagePlaceholder = "☕",
            TotalRatings = 18,
            RatingSum = 85
        }
    };

    private int _nextId = 7;
    private readonly object _lock = new();

    public List<Recipe> GetAllRecipes()
    {
        lock (_lock)
        {
            return _recipes.ToList();
        }
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
        }
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetRecipeById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public Recipe AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
            return recipe;
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe != null && stars >= 1 && stars <= 5)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }
}

