﻿@page "/"
@inject RecipeService RecipeService

<PageTitle>RecipeHub</PageTitle>

<div class="container text-center my-5">
    <h1 class="display-4 fw-bold">Welcome to RecipeHub</h1>
    <p class="lead text-muted">Discover and share delicious recipes from our community</p>
</div>

<div class="container">
    <h2 class="mb-4">Browse by Category</h2>
    <div class="row">
        @foreach (var category in categories)
        {
            var recipes = RecipeService.GetRecipesByCategory(category);
            var emoji = recipes.FirstOrDefault()?.ImagePlaceholder ?? "🍽️";
            <div class="col-md-3 mb-4">
                <a href="recipes/@category" class="text-decoration-none">
                    <div class="card h-100 text-center shadow-sm">
                        <div class="card-body">
                            <div style="font-size: 3rem;">@emoji</div>
                            <h5 class="card-title mt-2">@category</h5>
                            <p class="card-text text-muted">@recipes.Count recipe(s)</p>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>
</div>

