@page "/recipes/{Category}"
@inject RecipeService RecipeService

<PageTitle>Browse Recipes - RecipeHub</PageTitle>

<div class="container my-4">
    <h1>@(string.IsNullOrEmpty(Category) ? "All Recipes" : Category)</h1>

    @if (!string.IsNullOrEmpty(Category))
    {
        <a href="recipes" class="btn btn-outline-secondary btn-sm mb-3">← All Categories</a>
    }

    @foreach (var group in groupedRecipes)
    {
        <h3 class="mt-4 mb-3">@group.Key</h3>
        <div class="row">
            @foreach (var recipe in group.Value)
            {
                <div class="col-md-4 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <div class="text-center" style="font-size: 3rem;">@recipe.ImagePlaceholder</div>
